const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/specification_sections',
  qs: {
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    specification_area_id: 'SOME_STRING_VALUE',
    filter_set_id: 'SOME_STRING_VALUE',
    filter_division_id: 'SOME_STRING_VALUE',
    search_string: 'SOME_STRING_VALUE',
    'filters[division_ids]': 'SOME_ARRAY_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/specification_sections?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&specification_area_id=SOME_STRING_VALUE&filter_set_id=SOME_STRING_VALUE&filter_division_id=SOME_STRING_VALUE&search_string=SOME_STRING_VALUE&filters%5Bdivision_ids%5D=SOME_ARRAY_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
